// ── Point-in-polygon (ray casting) ──────────────────────────────────
function pointInRing(lng, lat, ring) {
  let inside = false;
  for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
    const [xi, yi] = ring[i];
    const [xj, yj] = ring[j];
    const intersect =
      (yi > lat) !== (yj > lat) &&
      lng < ((xj - xi) * (lat - yi)) / (yj - yi) + xi;
    if (intersect) inside = !inside;
  }
  return inside;
}

function pointInPolygon(lng, lat, polygon) {
  // polygon = array of rings, first is outer, rest are holes
  if (!pointInRing(lng, lat, polygon[0])) return false;
  for (let k = 1; k < polygon.length; k++) {
    if (pointInRing(lng, lat, polygon[k])) return false; // inside a hole
  }
  return true;
}

// Find which ward (phường/xã) a coordinate falls in. Returns ward object or null.
export function findWard(lat, lng) {
  for (const ward of WARDS) {
    const [minLng, minLat, maxLng, maxLat] = ward.bbox;
    if (lng < minLng || lng > maxLng || lat < minLat || lat > maxLat) continue;
    for (const polygon of ward.polygons) {
      if (pointInPolygon(lng, lat, polygon)) return ward;
    }
  }
  return null;
}
